/**
 * The root host (M-A1a): every root query the native engine sees must produce a classified plan — a native compile when
 * the root shape is supported, otherwise a {@link GenericRootPlan} hosting generic execution. A silent fallback to an
 * unclassified generic plan (a "hard decline") must be structurally impossible, and the empty-store gate must keep only
 * the store-dependent native proposals away, never the host itself: a VALUES-only query on an empty store is still
 * hosted.
 */
public class LmdbNativeGenericRootHostTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String FORCE_FLAG = "rdf4j.lmdb.nativeQueryEngine.forceRootGeneric";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		repository.init();
	}

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	private void loadData() {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.begin();
			ValueFactory vf = conn.getValueFactory();
			IRI p = vf.createIRI(EX, "p");
			conn.add(vf.createIRI(EX, "s1"), p, vf.createLiteral("Bravo"));
			conn.add(vf.createIRI(EX, "s2"), p, vf.createLiteral("alpha"));
			conn.commit();
		}
	}

	/**
	 * {@code hasStatementsInSource()} is a dataset-branch emptiness proof, not a statement count: an ordinary empty
	 * store still answers true, so a VALUES-only query compiles into a native ValuesPlan there — no statements
	 * required. This pins that the root host does not steal it (the umbrella plan's "empty-store gate" concern was a
	 * misdiagnosis; see the M-A1a ExecPlan's Surprises section).
	 */
	@Test
	public void valuesOnlyQueryOnEmptyStoreStaysNative() {
		String query = "SELECT ?x WHERE { VALUES ?x { \"a\" \"b\" } }";

		long hostedBefore = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
		long compiledBefore = LmdbNativeAggregateCompiler.COMPILED.get();
		List<String> rows = rows(query);

		assertThat(rows).containsExactly("x=\"a\"", "x=\"b\"");
		assertThat(LmdbNativeAggregateCompiler.COMPILED.get() - compiledBefore)
				.as("a VALUES-only query needs no statements and must compile natively even on an empty store")
				.isGreaterThanOrEqualTo(1);
		assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get() - hostedBefore)
				.as("a natively compiled root must not also be counted as hosted-generic")
				.isZero();
		assertThat(LmdbNativeAggregateCompiler.UNHOSTED_HARD_DECLINES.get())
				.as("root hard declines must be structurally unreachable")
				.isZero();
	}

	/**
	 * A root shape the native compiler declines must be hosted on an empty store too — the host itself is never gated
	 * on store contents.
	 */
	@Test
	public void rootDeclinedQueryOnEmptyStoreIsHostedAndCorrect() {
		String query = "SELECT ?x WHERE { VALUES ?x { \"b\" \"a\" } } ORDER BY LCASE(?x)";

		long hostedBefore = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
		List<String> rows = rows(query);

		assertThat(rows).containsExactly("x=\"a\"", "x=\"b\"");
		assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get() - hostedBefore)
				.as("a root-declined query on an empty store must reach the root host and be hosted generically")
				.isEqualTo(1);
	}

	/**
	 * ORDER BY over a computed expression is a root shape the native row compiler declines (its supported orders are
	 * plain variables). With the root stage pipeline on by default (M-F6 rollout) the wrapper stack compiles as a
	 * pipeline over a native inner root; with the pipeline kill switch off, the host must still classify the decline
	 * and execute the query generically — results identical to the pure generic arm either way.
	 */
	@Test
	public void rootDeclinedOrderByExpressionIsHostedAndCorrect() {
		loadData();
		String query = "SELECT ?o WHERE { ?s <" + EX + "p> ?o } ORDER BY LCASE(STR(?o))";

		long pipelinesBefore = LmdbNativeAggregateCompiler.PIPELINE_ROOTS.get();
		List<String> nativeRows = rows(query);
		assertThat(nativeRows).isEqualTo(genericRows(query));
		assertThat(LmdbNativeAggregateCompiler.PIPELINE_ROOTS.get() - pipelinesBefore)
				.as("by default the ORDER BY expression wrapper stack must compile as a pipeline root")
				.isEqualTo(1);

		withProperty(NativeRootPipeline.ENABLED_FLAG, "false", () -> {
			long hostedBefore = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
			List<String> hostedRows = rows(query);
			assertThat(hostedRows).isEqualTo(genericRows(query));
			assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get() - hostedBefore)
					.as("with the pipeline off the root-declined query must be hosted generically, not hard-declined")
					.isEqualTo(1);
		});
	}

	/** A natively supported root must keep compiling natively — the host must not steal supported shapes. */
	@Test
	public void supportedRootStaysNative() {
		loadData();
		String query = "SELECT ?s WHERE { ?s <" + EX + "p> ?o }";

		long hostedBefore = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
		long compiledBefore = LmdbNativeAggregateCompiler.COMPILED.get();
		List<String> nativeRows = rows(query);

		assertThat(nativeRows).containsExactlyInAnyOrder("s=" + EX + "s1", "s=" + EX + "s2");
		assertThat(LmdbNativeAggregateCompiler.COMPILED.get() - compiledBefore)
				.as("the supported root shape must still be claimed by the native compiler")
				.isGreaterThanOrEqualTo(1);
		assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get() - hostedBefore)
				.as("a natively compiled root must not also be counted as hosted-generic")
				.isZero();
	}

	/** Explain must classify the hosted plan so the coverage census can read decline reasons from explain output. */
	@Test
	public void explainClassifiesHostedGenericRoot() {
		loadData();
		String query = "SELECT ?o WHERE { ?s <" + EX + "p> ?o } ORDER BY LCASE(STR(?o))";

		try (SailRepositoryConnection conn = repository.getConnection()) {
			String explain = conn.prepareTupleQuery(query).explain(Explanation.Level.Optimized).toString();
			assertThat(explain)
					.as("by default the ORDER BY expression stack compiles as a pipeline root")
					.contains("RootPipeline");
		}
		withProperty(NativeRootPipeline.ENABLED_FLAG, "false", () -> {
			try (SailRepositoryConnection conn = repository.getConnection()) {
				String explain = conn.prepareTupleQuery(query).explain(Explanation.Level.Optimized).toString();
				assertThat(explain)
						.as("explain output must carry the genericHostedRoot classification")
						.contains(LmdbNativeExplain.KIND_GENERIC_HOSTED);
			}
		});
	}

	/**
	 * With {@code forceRootGeneric} on, even a natively supported root must be hosted generically — and no native claim
	 * may happen anywhere in the plan, because generic operators' lazy runtime {@code precompile} callbacks all land on
	 * the claim-suppressed strategy.
	 */
	@Test
	public void forceRootGenericHostsSupportedShapesWithoutNativeClaims() {
		loadData();
		String query = "SELECT ?s WHERE { ?s <" + EX + "p> ?o }";

		withProperty(FORCE_FLAG, "true", () -> {
			long compiledBefore = LmdbNativeAggregateCompiler.COMPILED.get();
			long hostedBefore = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
			List<String> rows = rows(query);

			assertThat(rows).containsExactlyInAnyOrder("s=" + EX + "s1", "s=" + EX + "s2");
			assertThat(LmdbNativeAggregateCompiler.COMPILED.get() - compiledBefore)
					.as("forceRootGeneric must suppress every native root claim")
					.isZero();
			assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get() - hostedBefore)
					.as("forceRootGeneric must host the query generically")
					.isEqualTo(1);
		});
	}

	/**
	 * In default mode a root-declined query's generic recursion still claims interior native fragments (its explain
	 * output contains a native plan for the pattern). Under {@code forceRootGeneric} those interior claims must be
	 * suppressed too — lexical suppression would miss the lazy runtime callbacks, so this pins the strategy-object
	 * suppression.
	 */
	@Test
	public void forceRootGenericSuppressesInteriorFragmentClaims() {
		loadData();
		String query = "SELECT ?o WHERE { ?s <" + EX + "p> ?o } ORDER BY LCASE(STR(?o))";

		try (SailRepositoryConnection conn = repository.getConnection()) {
			String defaultExplain = conn.prepareTupleQuery(query).explain(Explanation.Level.Optimized).toString();
			assertThat(defaultExplain)
					.as("default mode keeps the interior native fragment claim (today's physical plan)")
					.contains("NativeRows");
		}
		withProperty(FORCE_FLAG, "true", () -> {
			try (SailRepositoryConnection conn = repository.getConnection()) {
				String explain = conn.prepareTupleQuery(query).explain(Explanation.Level.Optimized).toString();
				assertThat(explain)
						.as("forceRootGeneric explain must classify the hosted root")
						.contains(LmdbNativeExplain.KIND_GENERIC_HOSTED);
				assertThat(explain)
						.as("forceRootGeneric must suppress interior native fragment claims")
						.doesNotContain("NativeRows");
			}
		});
	}

	private void withProperty(String name, String value, Runnable action) {
		String previous = System.getProperty(name);
		try {
			System.setProperty(name, value);
			action.run();
		} finally {
			if (previous == null) {
				System.clearProperty(name);
			} else {
				System.setProperty(name, previous);
			}
		}
	}

	private List<String> rows(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate())
					.stream()
					.map(LmdbNativeGenericRootHostTest::render)
					.collect(Collectors.toList());
		}
	}

	private List<String> genericRows(String query) {
		String previous = System.getProperty(NATIVE_FLAG);
		try {
			System.setProperty(NATIVE_FLAG, "false");
			return rows(query);
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private static String render(BindingSet bindings) {
		return bindings.getBindingNames()
				.stream()
				.sorted()
				.map(name -> name + "=" + bindings.getValue(name))
				.collect(Collectors.joining("|"));
	}
}
